import AppKit
import EventKit
import DiskArbitration

// MARK: - Clipboard

/// The last ten texts copied, in memory only and gone when RetroMac quits. What a password
/// manager or a secure field marks as concealed or transient never gets in (nspasteboard.org).
final class ClipboardHistory {
    static let limit = 10
    static let skipped: Set<String> = ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                                       "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"]
    private(set) var items: [String] = []
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    func start() {
        guard timer == nil else { return }
        lastChange = NSPasteboard.general.changeCount   // what was copied before stays out
        timer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] _ in self?.poll() }
    }

    func stop() { timer?.invalidate(); timer = nil; items.removeAll() }

    /// macOS can refuse RetroMac the clipboard (Privacy & Security ▸ Paste from Other Apps).
    var denied: Bool {
        if #available(macOS 15.4, *) { return NSPasteboard.general.accessBehavior == .alwaysDeny }
        return false
    }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.skipped), types.contains(NSPasteboard.PasteboardType.string.rawValue),
              !denied, let s = pb.string(forType: .string) else { return }
        Self.insert(s, into: &items)
    }

    static func insert(_ s: String, into items: inout [String]) {
        guard !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        items.removeAll { $0 == s }
        items.insert(s, at: 0)
        if items.count > limit { items.removeLast(items.count - limit) }
    }

    func copy(_ s: String) {
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.setString(s, forType: .string)
        lastChange = pb.changeCount
        Self.insert(s, into: &items)
    }
}

// MARK: - Note and to-dos

struct CompanionNotes: Codable, Equatable {
    struct Todo: Codable, Equatable, Identifiable {
        var id = UUID()
        var text: String
        var done = false
    }
    var note = ""
    var todos: [Todo] = []

    static func load() -> CompanionNotes {
        UserDefaults.standard.data(forKey: "companionNotes").flatMap { try? JSONDecoder().decode(CompanionNotes.self, from: $0) } ?? CompanionNotes()
    }
    func save() {
        if let d = try? JSONEncoder().encode(self) { UserDefaults.standard.set(d, forKey: "companionNotes") }
    }
}

// MARK: - Calendar and reminders

/// "In 10 minutes: …" for the next meeting, and reminders as they fall due. Reads Calendar's and
/// Reminders' own stores through EventKit; nothing leaves the Mac.
final class CompanionCalendar {
    struct Item: Identifiable {
        let id: String
        let title: String
        let start: Date?
        let link: URL?
        let reminder: EKReminder?
    }

    let store = EKEventStore()
    var onSoon: ((Item) -> Void)?
    var onDue: ((Item) -> Void)?
    private var timer: Timer?
    private var announced: Set<String> = []
    private var snoozed: [String: Date] = [:]

    static var authorized: Bool {
        EKEventStore.authorizationStatus(for: .event) == .fullAccess
            && EKEventStore.authorizationStatus(for: .reminder) == .fullAccess
    }
    static var denied: Bool {
        [EKEntityType.event, .reminder].contains { [.denied, .restricted].contains(EKEventStore.authorizationStatus(for: $0)) }
    }

    func requestAccess(_ done: @escaping (Bool) -> Void) {
        store.requestFullAccessToEvents { ok, _ in
            self.store.requestFullAccessToReminders { ok2, _ in
                DispatchQueue.main.async { done(ok && ok2) }
            }
        }
    }

    func start() {
        guard timer == nil, Self.authorized else { return }
        timer = Timer.scheduledTimer(withTimeInterval: 60, repeats: true) { [weak self] _ in self?.check() }
        DispatchQueue.main.asyncAfter(deadline: .now() + 5) { [weak self] in self?.check() }
    }

    func stop() { timer?.invalidate(); timer = nil }

    func snooze(_ item: Item, minutes: Double = 10) {
        snoozed[item.id] = Date().addingTimeInterval(minutes * 60)
        announced.remove(item.id)
    }

    func complete(_ item: Item) {
        guard let r = item.reminder else { return }
        r.isCompleted = true
        try? store.save(r, commit: true)
    }

    private func check() {
        let now = Date()
        for e in events(from: now, to: now.addingTimeInterval(10 * 60)) where e.start.map({ $0 > now }) ?? false {
            guard !announced.contains(e.id), (snoozed[e.id] ?? .distantPast) < now else { continue }
            announced.insert(e.id)
            onSoon?(e)
        }
        dueReminders(until: now) { [weak self] items in
            guard let self else { return }
            for r in items where !self.announced.contains(r.id) && (self.snoozed[r.id] ?? .distantPast) < now {
                self.announced.insert(r.id)
                self.onDue?(r)
            }
        }
    }

    func events(from: Date, to: Date) -> [Item] {
        guard Self.authorized else { return [] }
        let pred = store.predicateForEvents(withStart: from, end: to, calendars: nil)
        return store.events(matching: pred)
            .filter { !$0.isAllDay && $0.status != .canceled && !Self.declined($0) }
            .sorted { $0.startDate < $1.startDate }
            .map { e in
                Item(id: (e.eventIdentifier ?? e.title ?? "") + "@\(e.startDate.timeIntervalSince1970)", title: e.title ?? "Event",
                     start: e.startDate, link: Self.meetingLink([e.url?.absoluteString, e.location, e.notes]), reminder: nil)
            }
    }

    func dueReminders(until: Date, _ done: @escaping ([Item]) -> Void) {
        guard Self.authorized else { done([]); return }
        let pred = store.predicateForIncompleteReminders(withDueDateStarting: until.addingTimeInterval(-24 * 3600), ending: until, calendars: nil)
        store.fetchReminders(matching: pred) { list in
            let items = (list ?? []).map { r in
                Item(id: r.calendarItemIdentifier, title: r.title ?? "Reminder", start: r.dueDateComponents?.date, link: nil, reminder: r)
            }
            DispatchQueue.main.async { done(items) }
        }
    }

    /// The rest of today: meetings still to come and reminders due by tonight.
    func today(_ done: @escaping ([Item]) -> Void) {
        let now = Date()
        let end = Calendar.current.startOfDay(for: now).addingTimeInterval(24 * 3600)
        let events = self.events(from: now, to: end)
        dueReminders(until: end) { done(events + $0) }
    }

    private static func declined(_ e: EKEvent) -> Bool {
        e.attendees?.first(where: \.isCurrentUser)?.participantStatus == .declined
    }

    private static let meetingHosts = ["zoom.us", "teams.microsoft.com", "teams.live.com", "meet.google.com", "webex.com",
                                       "whereby.com", "gotomeeting.com", "facetime.apple.com", "meet.jit.si"]

    /// The first video-call link in an event's URL, location or notes.
    static func meetingLink(_ texts: [String?]) -> URL? {
        guard let detector = try? NSDataDetector(types: NSTextCheckingResult.CheckingType.link.rawValue) else { return nil }
        for text in texts.compactMap({ $0 }) {
            let found = detector.matches(in: text, range: NSRange(text.startIndex..., in: text)).compactMap(\.url)
            if let hit = found.first(where: { url in
                url.scheme == "https" && meetingHosts.contains { url.host?.hasSuffix($0) == true }
            }) { return hit }
        }
        return nil
    }
}

// MARK: - Mac watcher

/// Things worth a word: a finished download, a disk plugged in, a battery running low, a full
/// disk, a Time Machine backup long ago. All read locally.
final class MacWatcher {
    enum Notice {
        case downloaded([URL])
        case mounted(URL)
        case battery(Int)
        case diskFull(Int64)
        case oldBackup(days: Int)
    }
    var onNotice: ((Notice) -> Void)?

    private var downloadsSource: DispatchSourceFileSystemObject?
    private var knownDownloads: Set<String> = []
    private var pendingScan: DispatchWorkItem?
    private var timer: Timer?
    private var observers: [NSObjectProtocol] = []
    private var batteryWarned = false
    private var lastDiskWarning = Date.distantPast
    private var lastBackupWarning = Date.distantPast

    private static var downloads: URL { FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Downloads") }

    func start() {
        guard timer == nil else { return }
        watchDownloads()
        observers.append(NSWorkspace.shared.notificationCenter.addObserver(forName: NSWorkspace.didMountNotification, object: nil, queue: .main) { [weak self] n in
            guard let url = n.userInfo?[NSWorkspace.volumeURLUserInfoKey] as? URL, Self.isPluggedIn(url) else { return }
            self?.onNotice?(.mounted(url))
        })
        timer = Timer.scheduledTimer(withTimeInterval: 120, repeats: true) { [weak self] _ in self?.checkSlow() }
        DispatchQueue.main.asyncAfter(deadline: .now() + 30) { [weak self] in self?.checkSlow() }
    }

    func stop() {
        timer?.invalidate(); timer = nil
        downloadsSource?.cancel(); downloadsSource = nil
        observers.forEach { NSWorkspace.shared.notificationCenter.removeObserver($0) }
        observers.removeAll()
    }

    // Downloads

    private func watchDownloads() {
        knownDownloads = Set(Self.listDownloads())
        let fd = open(Self.downloads.path, O_EVTONLY)
        guard fd >= 0 else { return }
        let src = DispatchSource.makeFileSystemObjectSource(fileDescriptor: fd, eventMask: [.write, .rename], queue: .main)
        src.setEventHandler { [weak self] in self?.scheduleScan() }
        src.setCancelHandler { close(fd) }
        src.resume()
        downloadsSource = src
    }

    /// Browsers write under a temporary name and rename at the end; a second later the folder
    /// has settled.
    private func scheduleScan() {
        pendingScan?.cancel()
        let w = DispatchWorkItem { [weak self] in
            guard let self else { return }
            let now = Self.listDownloads()
            let fresh = Self.finished(now.filter { !self.knownDownloads.contains($0) })
            self.knownDownloads = Set(now)
            if !fresh.isEmpty { self.onNotice?(.downloaded(fresh.map { Self.downloads.appendingPathComponent($0) })) }
        }
        pendingScan = w
        DispatchQueue.main.asyncAfter(deadline: .now() + 1.5, execute: w)
    }

    private static func listDownloads() -> [String] {
        (try? FileManager.default.contentsOfDirectory(atPath: downloads.path)) ?? []
    }

    static let partial = ["download", "crdownload", "part", "partial", "tmp", "opdownload", "aria2"]
    static func finished(_ names: [String]) -> [String] {
        names.filter { !$0.hasPrefix(".") && !partial.contains(($0 as NSString).pathExtension.lowercased()) }.sorted()
    }

    // Disks

    /// A stick, a card or an external drive; not a disk image or the network.
    private static func isPluggedIn(_ url: URL) -> Bool {
        let v = try? url.resourceValues(forKeys: [.volumeIsEjectableKey, .volumeIsRemovableKey, .volumeIsLocalKey])
        guard v?.volumeIsLocal == true, v?.volumeIsEjectable == true || v?.volumeIsRemovable == true else { return false }
        guard let session = DASessionCreate(kCFAllocatorDefault),
              let disk = DADiskCreateFromVolumePath(kCFAllocatorDefault, session, url as CFURL),
              let desc = DADiskCopyDescription(disk) as? [String: Any] else { return true }
        return (desc[kDADiskDescriptionDeviceModelKey as String] as? String)?.contains("Disk Image") != true
    }

    // Battery, disk space, backup

    private func checkSlow() {
        let (fraction, charging) = BatteryModule.read()
        if let f = fraction {
            let pct = Int((f * 100).rounded())
            if pct > 20 || charging { batteryWarned = false }
            else if pct <= 10, !batteryWarned, Self.onBattery { batteryWarned = true; onNotice?(.battery(pct)) }
        }
        let now = Date()
        if now.timeIntervalSince(lastDiskWarning) > 24 * 3600,
           let v = try? URL(fileURLWithPath: NSHomeDirectory()).resourceValues(forKeys: [.volumeAvailableCapacityForImportantUsageKey, .volumeTotalCapacityKey]),
           let free = v.volumeAvailableCapacityForImportantUsage, let total = v.volumeTotalCapacity, total > 0,
           Self.diskNearlyFull(free: free, total: Int64(total)) {
            lastDiskWarning = now
            onNotice?(.diskFull(free))
        }
        if now.timeIntervalSince(lastBackupWarning) > 24 * 3600, let last = Self.lastBackup(),
           case let days = Int(now.timeIntervalSince(last) / 86_400), days >= 7 {
            lastBackupWarning = now
            onNotice?(.oldBackup(days: days))
        }
    }

    private static var onBattery: Bool {
        (IOPSGetProvidingPowerSourceType(IOPSCopyPowerSourcesInfo()?.takeRetainedValue())?.takeRetainedValue() as String?) == kIOPSBatteryPowerValue
    }

    static func diskNearlyFull(free: Int64, total: Int64) -> Bool {
        free < 10_000_000_000 || Double(free) / Double(total) < 0.05
    }

    /// The newest snapshot date of any Time Machine destination; nil when none is set up.
    /// shortcut: reads the preferences file, not tmutil (that needs Full Disk Access); if Apple
    /// stops writing SnapshotDates there, this stays silent rather than wrong.
    static func lastBackup(plist: URL = URL(fileURLWithPath: "/Library/Preferences/com.apple.TimeMachine.plist")) -> Date? {
        guard let dict = NSDictionary(contentsOf: plist) as? [String: Any],
              let dests = dict["Destinations"] as? [[String: Any]], !dests.isEmpty else { return nil }
        return dests.compactMap { ($0["SnapshotDates"] as? [Date])?.max() }.max()
    }
}

// MARK: - Tips

/// A Mac tip for the app in front, now and then: once per app per day and never more than one in
/// twenty minutes.
enum CompanionTips {
    static let byApp: [String: [String]] = [
        "com.apple.finder": [
            "Press Space on a file to look inside it without opening it (Quick Look).",
            "Hold Option while you drag a file to copy it instead of moving it.",
            "Press Command-Shift-. to show the hidden files, and again to hide them.",
            "Press Command-Delete to move the selection to the Trash."],
        "com.apple.Safari": [
            "Press Command-L to jump to the address field.",
            "Press Command-Shift-T to bring back the tab you just closed.",
            "Press Command-Shift-R for Reader, the page without the clutter."],
        "com.apple.mail": [
            "Press Command-Shift-D to send the message you are writing.",
            "Press Command-Option-F to search all mailboxes.",
            "Press Command-Shift-N to check for new mail."],
        "com.apple.TextEdit": [
            "Press Command-Shift-T to switch between plain and rich text.",
            "Hold Option and drag to select a rectangle of text."],
        "com.apple.Terminal": [
            "Drag a file into the window to type its full path.",
            "Press Command-K to clear the window.",
            "Type 'open .' to show the current folder in the Finder."],
        "com.apple.Preview": [
            "Hold Shift while you resize a selection to keep its proportions.",
            "Drag pages between two PDFs in the sidebar to combine them."],
        "com.apple.Notes": [
            "Press Command-Shift-L to turn lines into a checklist."],
        "com.apple.iWork.Pages": [
            "It looks like you're writing a letter! Command-Option-C copies a style, Command-Option-V pastes it."],
        "com.microsoft.Word": [
            "It looks like you're writing a letter! Command-Option-Shift-V pastes without the formatting."],
        "com.apple.Music": [
            "Press Command-L to jump to the song that is playing."],
        "com.apple.systempreferences": [
            "Press Command-F to search all settings by name."],
    ]
    static let general = [
        "Press Command-Shift-4, then Space, to take a picture of one window.",
        "Press Command-Space for Spotlight: it also does sums and converts units.",
        "Press Control-Command-Q to lock the screen.",
        "Hold Option while you click a menu bar icon for more details.",
        "Press Command-Option-Esc to force a stuck app to quit.",
    ]

    struct RetroTip {
        let text: String
        var tab: SettingsTab? = nil
        /// Only under themes whose name contains one of these (lowercased); nil for all.
        var themes: [String]? = nil
    }

    static let retro: [RetroTip] = [
        .init(text: "Your Mac makes no sound? Settings ▸ Sounds gives it clicking keys, a spinning hard drive and a fan.", tab: .sounds),
        .init(text: "A theme can start like the real thing: firmware, boot screen, desktop. Settings ▸ Themes ▸ Boot Phases.", tab: .dock),
        .init(text: "Settings ▸ Shader lays a CRT over the whole screen: scanlines, glow, a curved tube.", tab: .shader),
        .init(text: "Settings ▸ Favourite switches to your favourite look in one click, and back.", tab: .retroMode),
        .init(text: "Hid a desktop icon by mistake? Settings ▸ Desktop brings it back.", tab: .desktop),
        .init(text: "Settings ▸ Crashes: blue screens and bombs in period. Nothing ever really crashes.", tab: .crashes),
        .init(text: "Lost in a theme? Rescue Desktop (Control-Option-Command-R unless you changed it) turns everything off and keeps your settings.", tab: .shortcuts),
        .init(text: "Settings ▸ Health Check shows what RetroMac is doing right now.", tab: .health),
        .init(text: "Every theme puts a Read Me on its desktop with the story of the system it recreates."),
        .init(text: "Start ▸ All Programs lists every app on your Mac, sorted into folders.", themes: ["windows"]),
        .init(text: "Double-click sheep.exe on the desktop and a sheep walks along your taskbar.",
              themes: ["windows 95", "windows 98", "windows me", "windows xp"]),
        .init(text: "With Boot Phases on Firmware, press the BIOS setup key while the memory counts up to enter the setup.",
              tab: .dock, themes: ["windows"]),
        .init(text: "Dashboard and Exposé are back. Their hotkeys are in Settings ▸ Shortcuts.", tab: .shortcuts,
              themes: ["mac os x", "cheetah", "snow leopard", "mountain lion", "mavericks", "aqua"]),
    ]

    /// The next RetroMac tip that fits the theme, at most one an hour and never within twenty
    /// minutes of any other tip.
    static func nextRetro(themeName: String?, now: Date = Date(), defaults: UserDefaults = .standard) -> RetroTip? {
        let t = now.timeIntervalSince1970
        guard t - defaults.double(forKey: "companionRetroTipLast") > 3600,
              t - defaults.double(forKey: "companionTipLast") > 20 * 60 else { return nil }
        let name = themeName?.lowercased() ?? ""
        let fitting = retro.filter { $0.themes?.contains { name.contains($0) } ?? true }
        guard !fitting.isEmpty else { return nil }
        let i = defaults.integer(forKey: "companionRetroTipIndex")
        defaults.set(i + 1, forKey: "companionRetroTipIndex")
        defaults.set(t, forKey: "companionRetroTipLast")
        defaults.set(t, forKey: "companionTipLast")
        return fitting[i % fitting.count]
    }

    /// The tip for this app today, or nil when it already had one or the last was too recent.
    static func next(for bundleID: String, now: Date = Date(), defaults: UserDefaults = .standard) -> String? {
        let day = ISO8601DateFormatter.string(from: now, timeZone: .current, formatOptions: [.withFullDate])
        var shown = defaults.dictionary(forKey: "companionTipsShown") as? [String: String] ?? [:]
        guard shown[bundleID] != day,
              now.timeIntervalSince1970 - defaults.double(forKey: "companionTipLast") > 20 * 60 else { return nil }
        let list = byApp[bundleID] ?? general
        let count = defaults.integer(forKey: "companionTipIndex")
        shown[bundleID] = day
        defaults.set(shown, forKey: "companionTipsShown")
        defaults.set(now.timeIntervalSince1970, forKey: "companionTipLast")
        defaults.set(count + 1, forKey: "companionTipIndex")
        return list[count % list.count]
    }
}
